def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\s*(?:(\d+)|([A-Z]+(?:[1-9]\d?)?)|(<=|>=|<>|[+\-*/(),:=<>]))"
    )

    def parse(content):
        if not content.startswith("="):
            return ("num", int(content))

        tokens = []
        pos = 1
        while pos < len(content):
            match = token_pattern.match(content, pos)
            if match is None:
                if content[pos:].strip() == "":
                    break
                raise ValueError("Invalid formula")
            tokens.append(next(group for group in match.groups() if group is not None))
            pos = match.end()

        # Operator and value stacks implement an iterative expression parser.
        values = []
        operators = []
        frames = []
        index = 0
        expecting_operand = True
        precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "unary": 3}
        comparisons = {"=", "<>", "<", "<=", ">", ">="}

        def reduce_operator():
            op = operators.pop()
            if op == "unary":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        def reduce_until_marker():
            while operators and operators[-1] != "(":
                reduce_operator()

        while index < len(tokens):
            token = tokens[index]

            if expecting_operand:
                if token == "-":
                    operators.append("unary")
                    index += 1
                elif token == "(":
                    operators.append("(")
                    frames.append(("group", len(values)))
                    index += 1
                elif token in ("SUM", "MIN", "MAX", "IF"):
                    operators.append("(")
                    frames.append((token, len(values), [], None))
                    index += 2  # Skip the function name and opening parenthesis.
                elif token[0].isdigit():
                    values.append(("num", int(token)))
                    expecting_operand = False
                    index += 1
                else:
                    if index + 1 < len(tokens) and tokens[index + 1] == ":":
                        values.append(("range", token, tokens[index + 2]))
                        index += 3
                    else:
                        values.append(("ref", token))
                        index += 1
                    expecting_operand = False
            elif token in ("+", "-", "*", "/"):
                while (
                    operators
                    and operators[-1] != "("
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expecting_operand = True
                index += 1
            elif token in comparisons:
                reduce_until_marker()
                kind, base, args, _ = frames[-1]
                args.append(values.pop())
                frames[-1] = (kind, base, args, token)
                expecting_operand = True
                index += 1
            elif token == ",":
                reduce_until_marker()
                kind, base, args, comparison = frames[-1]
                args.append(values.pop())
                frames[-1] = (kind, base, args, comparison)
                expecting_operand = True
                index += 1
            else:  # Closing parenthesis.
                reduce_until_marker()
                operators.pop()
                frame = frames.pop()
                if frame[0] != "group":
                    kind, base, args, comparison = frame
                    args.append(values.pop())
                    if kind == "IF":
                        values.append(
                            ("if", comparison, args[0], args[1], args[2], args[3])
                        )
                    else:
                        values.append(("func", kind, args))
                expecting_operand = False
                index += 1

        while operators:
            reduce_operator()
        return values[0]

    trees = {name: parse(content) for name, content in cells.items()}
    results = {}
    active = set()

    def is_error(value):
        return isinstance(value, str)

    def evaluate(start):
        # Each stack entry is an instruction; intermediate values use a
        # separate stack so even a full-sheet reference chain is safe.
        stack = [("cell", start)]
        value_stack = []

        while stack:
            instruction = stack.pop()
            action = instruction[0]

            if action == "cell":
                name = instruction[1]
                if name in results:
                    value_stack.append(results[name])
                elif name in active:
                    value_stack.append("#CYCLE!")
                elif name not in trees:
                    value_stack.append(0)
                else:
                    active.add(name)
                    stack.append(("finish_cell", name))
                    stack.append(("eval", trees[name]))

            elif action == "finish_cell":
                name = instruction[1]
                results[name] = value_stack[-1]
                active.remove(name)

            elif action == "eval":
                node = instruction[1]
                kind = node[0]
                if kind == "num":
                    value_stack.append(node[1])
                elif kind == "ref":
                    stack.append(("cell", node[1]))
                elif kind == "neg":
                    stack.append(("neg",))
                    stack.append(("eval", node[1]))
                elif kind == "binary":
                    stack.append(("binary_left", node[1], node[3]))
                    stack.append(("eval", node[2]))
                elif kind == "if":
                    stack.append(("if_left", node))
                    stack.append(("eval", node[2]))
                else:
                    stack.append(("func_next", node[1], node[2], 0, None))

            elif action == "neg":
                value = value_stack.pop()
                value_stack.append(value if is_error(value) else -value)

            elif action == "binary_left":
                left = value_stack.pop()
                if is_error(left):
                    value_stack.append(left)
                else:
                    stack.append(("binary_right", instruction[1], left))
                    stack.append(("eval", instruction[2]))

            elif action == "binary_right":
                op, left = instruction[1], instruction[2]
                right = value_stack.pop()
                if is_error(right):
                    value_stack.append(right)
                elif op == "+":
                    value_stack.append(left + right)
                elif op == "-":
                    value_stack.append(left - right)
                elif op == "*":
                    value_stack.append(left * right)
                elif right == 0:
                    value_stack.append("#DIV/0!")
                else:
                    quotient = abs(left) // abs(right)
                    value_stack.append(-quotient if (left < 0) != (right < 0) else quotient)

            elif action == "if_left":
                node = instruction[1]
                left = value_stack.pop()
                if is_error(left):
                    value_stack.append(left)
                else:
                    stack.append(("if_right", node, left))
                    stack.append(("eval", node[3]))

            elif action == "if_right":
                node, left = instruction[1], instruction[2]
                right = value_stack.pop()
                if is_error(right):
                    value_stack.append(right)
                else:
                    op = node[1]
                    if op == "=":
                        condition = left == right
                    elif op == "<>":
                        condition = left != right
                    elif op == "<":
                        condition = left < right
                    elif op == "<=":
                        condition = left <= right
                    elif op == ">":
                        condition = left > right
                    else:
                        condition = left >= right
                    stack.append(("eval", node[4] if condition else node[5]))

            elif action == "func_next":
                func, args, index, aggregate = instruction[1:]
                if index == len(args):
                    value_stack.append(0 if aggregate is None else aggregate)
                else:
                    arg = args[index]
                    if arg[0] == "range":
                        first, last = arg[1], arg[2]
                        col1, col2 = sorted((ord(first[0]), ord(last[0])))
                        row1, row2 = sorted((int(first[1:]), int(last[1:])))
                        names = [
                            chr(col) + str(row)
                            for row in range(row1, row2 + 1)
                            for col in range(col1, col2 + 1)
                            if chr(col) + str(row) in trees
                        ]
                        stack.append(
                            ("range_next", func, args, index, aggregate, names, 0)
                        )
                    else:
                        stack.append(("func_collect", func, args, index, aggregate))
                        stack.append(("eval", arg))

            elif action == "range_next":
                func, args, index, aggregate, names, offset = instruction[1:]
                if offset == len(names):
                    stack.append(("func_next", func, args, index + 1, aggregate))
                else:
                    stack.append(
                        ("range_collect", func, args, index, aggregate, names, offset)
                    )
                    stack.append(("cell", names[offset]))

            elif action in ("func_collect", "range_collect"):
                func, args, index, aggregate = instruction[1:5]
                value = value_stack.pop()
                if is_error(value):
                    value_stack.append(value)
                else:
                    if aggregate is None:
                        aggregate = value
                    elif func == "SUM":
                        aggregate += value
                    elif func == "MIN":
                        aggregate = min(aggregate, value)
                    else:
                        aggregate = max(aggregate, value)

                    if action == "func_collect":
                        stack.append(("func_next", func, args, index + 1, aggregate))
                    else:
                        names, offset = instruction[5:]
                        stack.append(
                            ("range_next", func, args, index, aggregate, names, offset + 1)
                        )

        return value_stack.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
